import{U as e,gt as t,nt as n,rt as r}from"./chunks/framework.B3obAz7o.js";var i=JSON.parse(`{"title":"公开契约","description":"","frontmatter":{},"headers":[],"relativePath":"zh/contracts.md","filePath":"zh/contracts.md","lastUpdated":1785216853000}`),a={name:`zh/contracts.md`};function o(e,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[r(`<h1 id="公开契约" tabindex="-1">公开契约 <a class="header-anchor" href="#公开契约" aria-label="Permalink to “公开契约”">​</a></h1><p>稳定公开边界记录在 <a href="https://github.com/fontmin-rs/fontmin-rs/blob/main/contracts/public-api.json" target="_blank" rel="noreferrer"><code>contracts/public-api.json</code></a> 中。CI 会将实现与这份机器可读清单比较。修改清单代表一次明确的兼容性决策，必须在同一个 PR 中同步更新 Changelog、迁移说明和相关测试。</p><h2 id="cli" tabindex="-1">CLI <a class="header-anchor" href="#cli" aria-label="Permalink to “CLI”">​</a></h2><p><code>build</code>、<code>subset</code>、<code>coverage</code>、<code>inspect</code>、<code>convert</code>、<code>bench</code>、<code>init</code> 和 <code>doctor</code> 命令，以及清单列出的长参数都被冻结。命令成功时退出码为 <code>0</code>；参数、配置、 I/O 或处理失败时退出码为 <code>1</code>。如果错误带有稳定 diagnostic code，脚本还应优先按 code 分支。</p><p>帮助信息的排版、空白、终端颜色和面向人的措辞不属于冻结范围；命令名、可接受参数、退出码 和 diagnostic code 属于冻结范围。</p><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to “配置”">​</a></h2><p>Rust CLI、Node 包和浏览器 WASM 包有意采用不同边界：</p><ul><li>Rust 接受项目字段、可序列化的内置 plugin descriptor，以及文档列出的六种配置扩展名。</li><li>Node 接受文件系统或内存输入、自定义 plugin hooks，以及 <code>runtime: &quot;native&quot; | &quot;wasm&quot; | &quot;auto&quot;</code>。</li><li>浏览器 WASM 只接受内存中的 <code>assets</code> 和 <code>plugins</code>。</li></ul><p>精确的顶层字段记录在契约清单中；选项行为和嵌套字段继续以<a href="./guide/config">配置文档</a> 为准。</p><h2 id="javascript-exports-与-plugin-生命周期" tabindex="-1">JavaScript exports 与 plugin 生命周期 <a class="header-anchor" href="#javascript-exports-与-plugin-生命周期" aria-label="Permalink to “JavaScript exports 与 plugin 生命周期”">​</a></h2><p><code>fontmin-rs</code> 主入口、<code>./plugins</code>、<code>./presets</code>、<code>./compat</code> 子路径，以及 <code>@fontmin-rs/wasm</code> 的运行时导出名称被冻结。仅类型导出遵循相同兼容策略，并由 TypeScript 编译测试把关。</p><p>Node plugin 按 <code>buildStart</code>、<code>transform</code>、<code>generateBundle</code>、<code>buildEnd</code> 的顺序 执行。破坏性的 hook 签名或顺序变化必须遵循弃用策略，并进行明确的版本规划。</p><h2 id="diagnostics-与文件命名" tabindex="-1">Diagnostics 与文件命名 <a class="header-anchor" href="#diagnostics-与文件命名" aria-label="Permalink to “Diagnostics 与文件命名”">​</a></h2><p>Rust 产生的稳定诊断使用清单列出的 <code>fontmin::*</code> code，包括 <code>fontmin::invalid_font</code>。Node 与 WASM 通过 <code>FontminDiagnosticError</code> 暴露这些 code。</p><p>生成文件遵循以下模板：</p><table tabindex="0"><thead><tr><th>输出</th><th>模板</th></tr></thead><tbody><tr><td>普通 transform</td><td><code>{stem}.{extension}</code></td></tr><tr><td>命名 Unicode delivery slice</td><td><code>{stem}-{slice}.{extension}</code></td></tr><tr><td>SVG icon font 默认 stem</td><td><code>iconfont</code></td></tr><tr><td>保留的原始输入</td><td><code>{input-file-name}</code></td></tr></tbody></table><p>显式的 <code>fileName</code>、<code>ext</code> 或 icon-font <code>fontName</code> 会覆盖对应默认值。测试冻结代表性 输出集合和 CSS URL，不承诺编码器输出字节完全一致。</p><h2 id="兼容性规则" tabindex="-1">兼容性规则 <a class="header-anchor" href="#兼容性规则" aria-label="Permalink to “兼容性规则”">​</a></h2><p>即使是新增能力，也必须更新清单并通过完整发布门禁。删除或修改现有项应遵循 <a href="./deprecation">弃用策略</a>。未来的 <code>1.0.0</code> 会运行独立版本的 RC 周期，再最终 确定其公开契约。</p>`,19)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};